<?= $this->extend('layouts/app') ?>
<?= $this->section('content') ?>
<div class="page-heading compact"><a class="text-link" href="<?= site_url($resource) ?>">&larr; <?= esc($spec['title']) ?></a><p class="eyebrow form-eyebrow">STORE MANAGEMENT</p><h1><?= esc($title) ?></h1><p class="lead">Fields marked * are required.</p></div>
<form class="account-form" action="<?= site_url($resource.($row ? '/'.$row['id'] : '')) ?>" method="POST" enctype="multipart/form-data"><?= csrf_field() ?>
<div class="form-header"><h2><?= esc($spec['singular']) ?> details</h2></div><div class="form-grid">
<?php foreach ($spec['fields'] as $name => [$label, $type, $required]): ?><?php $isPassword = $type === 'password'; $needed = $required && (! $isPassword || ! $row); ?>
