<?php endforeach ?>
<?php if ($resource === 'staff'): ?><div class="field"><label for="password_confirmation">Confirm password<?= ! $row ? ' *' : '' ?></label><input id="password_confirmation" name="password_confirmation" type="password" <?= ! $row ? 'required' : '' ?> autocomplete="new-password"></div><?php endif ?>
</div>
<?php if ($spec['image']): ?><section class="avatar-section"><img class="<?= $resource === 'staff' ? 'avatar-preview' : 'product-preview' ?>" src="<?= record_image($row[$spec['image']] ?? null, $spec['kind']) ?>" alt="Current picture" width="<?= $resource === 'staff' ? 96 : 160 ?>" height="<?= $resource === 'staff' ? 96 : 120 ?>"><div class="field"><label for="picture"><?= $resource === 'staff' ? 'Staff avatar' : 'Product picture' ?></label><input type="file" name="picture" id="picture" accept="image/jpeg,image/png,image/webp"><p class="field-hint">JPEG, PNG, or WebP. Up to 2 MB and 4096 × 4096 pixels. Prepared as a <?= $resource === 'staff' ? '256 × 256 avatar' : '640 × 480 product image' ?>. Leave blank to keep the current picture.</p><p class="field-hint">Choose your file again after a validation error.</p></div></section><?php endif ?>
<div class="form-actions"><button class="button" type="submit"><?= $row ? 'Save changes' : 'Create '.esc(strtolower($spec['singular'])) ?></button><a class="button secondary" href="<?= site_url($resource) ?>">Cancel</a></div></form>
<?= $this->endSection() ?>
